function showThankYouMessage() {
  (thankYouMessage.style.display = "inline"),
    setTimeout(function () {
      $("#exampleModalCenter").modal("hide");
    }, 3e3);
}
const thankYouMessage = document.getElementById("thank-you");
var request;
$("#subscriptionForm").submit(function (e) {
  $("#subscribeButton").text("Sending . . .").attr("disabled", !0);
  var t =
    "https://script.google.com/a/macros/apurva.ai/s/AKfycbyS1sVnrtj1HmtZ-S-abBHrVfUw4a6Mq7dOS_W3xpzHQolIuBBizfFfrdVi7evP1B-Z/exec";
  request && request.abort();
  var s = $(this),
    a = s.find("input, select, button, textarea"),
    n = s.serialize();
  a.prop("disabled", !0),
    (request = $.ajax({ url: t, type: "GET", data: n })),
    request.done(function (e) {
      showThankYouMessage();
    }),
    request.fail(function (e, t, s) {
      $("#subscriptionForm").reset();
    }),
    request.always(function () {
      $("#subscribeButton").text("Send Message"), a.prop("disabled", !1);
    }),
    e.preventDefault();
});
